import { loadFont } from "@remotion/google-fonts/Baloo2";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// Salve o Pietro · aniversário 11/11 — v2 (04/11, o diretor: "texto muito embaixo, mais destaque e mais inversão com motions,
// textos mais destaques e menos legendas"). Cenas de motion (fundo azul, branco e verde, cores do site) intercaladas com as
// fotos e vídeos; nas cenas com imagem, o texto sobe para o meio do quadro, grande, com a palavra-chave numa caixa verde.
// Mesma voz e mesmos tempos da v1 (public/gabriel-alberti/pietro/voz-dinamica.wav, LEAD 0,15).

const { fontFamily: F } = loadFont("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const PA2_FPS = 30;
const FPS = PA2_FPS;
const LEAD = 0.15;
export const PA2_FRAMES = Math.round(31.8 * FPS);

const NAVY = "#04264d";
const NAVY2 = "#06366d";
const BLUE = "#3b8ddf";
const GREEN = "#4ade80";
const GREEN_D = "#16a34a";
const PINK = "#ff5c8a";
const YELLOW = "#ffd23f";
const WHITE = "#f4f8ff";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IO = Easing.inOut(Easing.sin);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 12, stiffness = 210) => spring({ frame: Math.round((t - a) * FPS), fps: FPS, config: { damping, stiffness } });
const src = (f: string) => staticFile(`gabriel-alberti/pietro/${f}`);

// ───────── texto ─────────
// palavra que entra com impulso e fica parada
const Pop: React.FC<{ t: number; at: number; style?: React.CSSProperties; from?: "big" | "up" | "side"; children: React.ReactNode }> = ({ t, at, style, from = "big", children }) => {
  if (t < at - 0.02) return null;
  const s = sp(t, at);
  const tf = from === "big" ? `scale(${(1.5 - 0.5 * s).toFixed(3)})` : from === "up" ? `translateY(${((1 - s) * 80).toFixed(1)}px)` : `translateX(${((1 - s) * -140).toFixed(1)}px)`;
  return <div style={{ fontFamily: F, textAlign: "center", whiteSpace: "nowrap", opacity: Math.min(1, s * 3), transform: tf, ...style }}>{children}</div>;
};
// palavra-chave numa caixa (verde com letra azul, ou invertida)
const Box: React.FC<{ t: number; at: number; size: number; bg?: string; fg?: string; rot?: number; children: React.ReactNode; after?: React.ReactNode }> = ({ t, at, size, bg = GREEN, fg = NAVY, rot = -2, children, after }) => {
  if (t < at - 0.02) return null;
  const s = sp(t, at, 11, 230);
  return (
    <div style={{ display: "inline-flex", alignItems: "center", gap: size * 0.18, padding: `${size * 0.04}px ${size * 0.26}px ${size * 0.02}px`, borderRadius: size * 0.2, background: bg, boxShadow: "0 22px 60px rgba(0,0,0,0.35)",
      fontFamily: F, fontWeight: 800, fontSize: size, lineHeight: 1.08, color: fg, whiteSpace: "nowrap", letterSpacing: "-0.01em",
      opacity: Math.min(1, s * 3), transform: `rotate(${rot}deg) scale(${(0.4 + 0.6 * s).toFixed(3)})` }}>
      {children}{after}
    </div>
  );
};
const shadow = "0 4px 22px rgba(2,20,45,0.8), 0 0 3px rgba(2,20,45,0.6)";
// bloco de texto no meio do quadro, centralizado; cada frase some inteira antes da próxima
const Block: React.FC<{ t: number; a: number; out: number; top: number; gap?: number; children: React.ReactNode }> = ({ t, a, out, top, gap = 18, children }) => {
  if (t < a - 0.05 || t > out + 0.16) return null;
  const o = lin(t, out, out + 0.14);
  return (
    <div style={{ position: "absolute", left: 100, right: 100, top, display: "flex", flexDirection: "column", alignItems: "center", gap, opacity: 1 - o, transform: `scale(${(1 - 0.06 * o).toFixed(3)})` }}>{children}</div>
  );
};

// ───────── ícones ─────────
const HEART_D = "M12 21s-7.5-4.6-9.6-9.2C.9 8.4 3 4.5 6.8 4.5c2.1 0 3.6 1.1 5.2 3 1.6-1.9 3.1-3 5.2-3 3.8 0 5.9 3.9 4.4 7.3C19.5 16.4 12 21 12 21z";
const Heart: React.FC<{ s: number; c?: string }> = ({ s, c = PINK }) => <svg width={s} height={s} viewBox="0 0 24 24"><path d={HEART_D} fill={c} /></svg>;
const HeartDraw: React.FC<{ e: number; s: number }> = ({ e, s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" style={{ overflow: "visible" }}>
    <path d={HEART_D} fill={PINK} fillOpacity={Math.max(0, (e - 0.6) / 0.4)} stroke={PINK} strokeWidth={1.8} strokeLinejoin="round" pathLength={1} strokeDasharray="1" strokeDashoffset={(1 - Math.min(1, e / 0.7)).toFixed(3)} />
  </svg>
);
const Gift: React.FC<{ s: number; e: number; open?: number; c?: string }> = ({ s, e, open = 0, c = GREEN }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" style={{ overflow: "visible", opacity: Math.min(1, e * 2), transform: `scale(${(0.5 + 0.5 * e).toFixed(3)})` }}>
    <rect x="3.5" y="10.5" width="17" height="11" rx="1.6" fill={c} />
    <rect x="10.6" y="10.5" width="2.8" height="11" fill={PINK} />
    <g transform={`translate(${(3 * open).toFixed(2)} ${(-7 * open).toFixed(2)}) rotate(${(24 * open).toFixed(2)} 20 8)`}>
      <rect x="2.5" y="6.8" width="19" height="4" rx="1.2" fill={c} stroke={NAVY} strokeWidth={0.4} />
      <rect x="10.6" y="6.8" width="2.8" height="4" fill={PINK} />
      <path d="M12 6.8c-1.2-3-4.6-3.6-4.8-1.6-.2 1.6 2.6 1.6 4.8 1.6zm0 0c1.2-3 4.6-3.6 4.8-1.6.2 1.6-2.6 1.6-4.8 1.6z" fill={PINK} />
    </g>
  </svg>
);
const PLANE_D = "M21 16v-2l-8-5V3.5a1.5 1.5 0 0 0-3 0V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5l8 2.5z";

// confete: estoura uma vez e cai para fora do quadro
const CONF = Array.from({ length: 80 }, (_, i) => {
  const r = (n: number) => { const x = Math.sin(i * 12.9898 + n * 78.233) * 43758.5453; return x - Math.floor(x); };
  return { ang: -Math.PI / 2 + (r(1) - 0.5) * 2.4, v: 1600 + r(2) * 1600, c: [GREEN, PINK, YELLOW, BLUE, "#ffffff"][i % 5], w: 14 + r(3) * 16, h: 8 + r(4) * 10, spin: (r(5) - 0.5) * 1400, dl: r(6) * 0.12 };
});
const Confetti: React.FC<{ t: number; at: number; x: number; y: number }> = ({ t, at, x, y }) => {
  if (t < at || t > at + 2.6) return null;
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      {CONF.map((p, i) => {
        const e = Math.max(0, t - at - p.dl);
        const drag = (1 - Math.exp(-e * 2.6)) / 2.6;
        return <div key={i} style={{ position: "absolute", left: x + Math.cos(p.ang) * p.v * drag, top: y + Math.sin(p.ang) * p.v * drag + 550 * e * e, width: p.w, height: p.h, borderRadius: 3, background: p.c, opacity: e > 0 ? 1 : 0, transform: `rotate(${(p.spin * e).toFixed(1)}deg) scaleX(${Math.cos(e * 9 + i).toFixed(3)})` }} />;
      })}
    </AbsoluteFill>
  );
};

// ───────── cenas ─────────
type Kind = { img?: string; vid?: string; from?: number; rate?: number; wide?: boolean; z: [number, number]; o: string; pan?: [number, number]; bg?: string };
type Tr = "punch" | "slideUp" | "slideL" | "iris" | "blur";
const TD = 0.32;
const Shot: React.FC<{ t: number; a: number; b: number; tr: Tr; m: Kind; first?: boolean; children?: React.ReactNode }> = ({ t, a, b, tr, m, first, children }) => {
  if (t < a || t > b + TD) return null;
  const q = first ? 1 : k(t, a, TD);
  let tf = "", clip = "none", op = 1, filter: string | undefined;
  if (tr === "punch") { tf = `scale(${(1.25 - 0.25 * q).toFixed(4)})`; op = Math.min(1, q * 2); }
  if (tr === "slideUp") tf = `translateY(${((1 - q) * 100).toFixed(2)}%)`;
  if (tr === "slideL") tf = `translateX(${((1 - q) * 100).toFixed(2)}%)`;
  if (tr === "iris") clip = `circle(${(q * 125).toFixed(2)}% at 50% 50%)`;
  if (tr === "blur") { op = q; filter = q < 1 ? `blur(${((1 - q) * 14).toFixed(1)}px)` : undefined; }
  const u = interpolate(t, [a, b + TD], [0, 1], { ...cl, easing: first ? Easing.out(Easing.cubic) : IO });
  const sc = m.z[0] + (m.z[1] - m.z[0]) * u;
  const px = m.pan ? m.pan[0] + (m.pan[1] - m.pan[0]) * u : 0;
  const cover: React.CSSProperties = { width: "100%", height: "100%", objectFit: "cover", transform: `translateX(${px.toFixed(1)}px) scale(${sc.toFixed(4)})`, transformOrigin: m.o };
  const media = (style: React.CSSProperties) =>
    m.img ? <Img src={src(m.img)} style={style} /> : m.vid ? <OffthreadVideo src={src(m.vid)} muted trimBefore={Math.round((m.from ?? 0) * FPS)} playbackRate={m.rate ?? 1} style={style} /> : null;
  const wideH = 1080 * (480 / 848);
  return (
    <AbsoluteFill style={{ transform: tf || undefined, clipPath: clip, opacity: op, filter, overflow: "hidden", background: m.bg ?? NAVY }}>
      {m.wide ? (
        <Sequence from={Math.round((a + LEAD) * FPS)} layout="none">
          <AbsoluteFill>{media({ ...cover, transform: `scale(${(1.3 * sc).toFixed(4)})`, filter: "blur(34px) brightness(0.55)" })}</AbsoluteFill>
          <div style={{ position: "absolute", left: 0, top: 380, width: 1080, height: wideH, overflow: "hidden", boxShadow: "0 30px 80px rgba(0,0,0,0.45)" }}>
            {media({ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${(1.04 + 0.12 * u).toFixed(4)})`, transformOrigin: "25% 50%" })}
          </div>
        </Sequence>
      ) : m.vid ? (
        <Sequence from={Math.round((a + LEAD) * FPS)} layout="none"><AbsoluteFill>{media(cover)}</AbsoluteFill></Sequence>
      ) : m.img ? (
        <AbsoluteFill>{media(cover)}</AbsoluteFill>
      ) : null}
      {(m.img || m.vid) && !m.wide ? <AbsoluteFill style={{ background: "radial-gradient(90% 60% at 50% 55%, rgba(4,38,77,0.45) 0%, rgba(4,38,77,0.12) 70%), linear-gradient(180deg, rgba(4,38,77,0.35) 0px, rgba(4,38,77,0) 300px)" }} /> : null}
      {/* cenas de motion: a câmera aproxima devagar o conjunto */}
      <AbsoluteFill style={{ transform: !m.img && !m.vid ? `scale(${(1 + 0.07 * u).toFixed(4)})` : undefined }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

