        opacity: Math.min(1, c * 3), transform: `translateY(${((1 - c) * -500).toFixed(1)}px) rotate(${((1 - c) * -18 - 3).toFixed(1)}deg)` }}>
        <div style={{ height: 150, background: GREEN, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 800, fontSize: 64, letterSpacing: "0.12em", color: NAVY }}>NOVEMBRO</div>
        <div style={{ height: 410, display: "flex", alignItems: "center", justifyContent: "center", perspective: 900 }}>
          <div style={{ fontFamily: F, fontWeight: 800, fontSize: 300, lineHeight: 1, color: NAVY, letterSpacing: "-0.04em", transform: `rotateX(${((1 - flip) * 90).toFixed(1)}deg)`, transformOrigin: "50% 0%" }}>11</div>
        </div>
      </div>
      <div style={{ position: "absolute", left: 100, right: 100, top: 960, display: "flex", flexDirection: "column", alignItems: "center", gap: 18 }}>
        <Pop t={t} at={1.31} style={{ fontWeight: 800, fontSize: 132, color: "#fff", letterSpacing: "-0.01em" }}>ANIVERSÁRIO</Pop>
        <Pop t={t} at={1.9} from="up" style={{ fontWeight: 600, fontSize: 70, color: "rgba(255,255,255,0.9)" }}>do</Pop>
        <Box t={t} at={2.02} size={170} rot={-3} after={<Heart s={130} c={PINK} />}>PIETRO</Box>
