      <div style={{ position: "absolute", left: 160, right: 160, top: 1500, display: "flex", flexWrap: "wrap", justifyContent: "center", gap: 14 }}>
        {Array.from({ length: 33 }, (_, i) => (
          <div key={i} style={{ width: 30, height: 30, borderRadius: 99, background: i < days ? GREEN_D : "rgba(4,38,77,0.12)", transform: `scale(${i < days ? 1 : 0.8})` }} />
