// H · motion azul: rota Brasil → México
const SH: React.FC<{ t: number }> = ({ t }) => {
  const A = 17.8;
  const draw = interpolate(t, [A + 0.3, 19.7], [0, 1], { ...cl, easing: IO });
  const P = (u: number) => { const x0 = 790, y0 = 1180, cx = 560, cy = 640, x1 = 290, y1 = 860; return [(1 - u) ** 2 * x0 + 2 * (1 - u) * u * cx + u * u * x1, (1 - u) ** 2 * y0 + 2 * (1 - u) * u * cy + u * u * y1]; };
  const [px, py] = P(draw); const [qx, qy] = P(Math.min(1, draw + 0.01));
  const ang = (Math.atan2(qy - py, qx - px) * 180) / Math.PI + 90;
  const Pin: React.FC<{ x: number; y: number; label: string; e: number; c: string }> = ({ x, y, label, e, c }) => (
    <div style={{ position: "absolute", left: x - 170, top: y - 30, width: 340, display: "flex", flexDirection: "column", alignItems: "center", opacity: Math.min(1, e * 2), transform: `scale(${(0.5 + 0.5 * e).toFixed(3)})` }}>
      <div style={{ width: 60, height: 60, borderRadius: 99, background: c, border: "8px solid #fff" }} />
      <div style={{ marginTop: 12, fontFamily: F, fontWeight: 800, fontSize: 56, color: "#fff" }}>{label}</div>
    </div>
  );
  return (
    <>
      <AbsoluteFill style={{ background: `radial-gradient(120% 70% at 50% 45%, ${NAVY2} 0%, ${NAVY} 62%, #021a36 100%)` }} />
      <div style={{ position: "absolute", left: 100, right: 100, top: 300, display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
        <Pop t={t} at={17.84} from="up" style={{ fontWeight: 700, fontSize: 76, color: "#fff" }}>chegar mais perto do</Pop>
        <Pop t={t} at={18.95} style={{ fontWeight: 800, fontSize: 120, color: "#fff" }}>TRATAMENTO</Pop>
      </div>
      <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}>
        <defs><mask id="rota2"><path d="M790 1180 Q560 640 290 860" fill="none" stroke="#fff" strokeWidth={18} pathLength={1} strokeDasharray={`${draw.toFixed(4)} 1`} /></mask></defs>
        <path d="M790 1180 Q560 640 290 860" fill="none" stroke="#fff" strokeWidth={8} strokeLinecap="round" strokeDasharray="2 24" mask="url(#rota2)" />
      </svg>
      <Pin x={790} y={1180} label="Brasil" e={k(t, 17.9, 0.5)} c={BLUE} />
      <Pin x={290} y={860} label="México" e={k(t, 19.6, 0.5)} c={GREEN} />
      <div style={{ position: "absolute", left: px - 55, top: py - 55, width: 110, height: 110, transform: `rotate(${ang.toFixed(1)}deg)`, opacity: t > A + 0.25 ? 1 : 0 }}>
        <svg width={110} height={110} viewBox="0 0 24 24"><path d={PLANE_D} fill={GREEN} /></svg>
      </div>
      <div style={{ position: "absolute", left: 100, right: 100, top: 1420, display: "flex", justifyContent: "center" }}>
        <Box t={t} at={19.7} size={170} rot={-3}>MÉXICO</Box>
      </div>
    </>
  );
};

